\title{Mixed-Radix Positional Systems: Existence, Uniqueness, and a Bijection Beyond Base-$N$}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\begin{abstract}
The familiar base-$b$ positional numeral system is the \emph{uniform} special case of a strictly
more general structure in which each position is permitted to carry its own, independently chosen
base. We develop this \emph{mixed-radix} (variable-base, or ``alien'') positional system in full.
A system is specified by a finite list of bases $bs = [b_0, \dots, b_{k-1}]$; a digit list
$ds = [d_0, \dots, d_{k-1}]$ denotes the value $\mval(bs, ds) = d_0 + b_0(d_1 + b_1(d_2 + \cdots))$
(a Horner evaluation), and a greedy extraction map $\mdigits(bs, n)$ recovers digits by successive
Euclidean division. Our central result is the master reconstruction law
$\mval(bs, \mdigits(bs, n)) = n \bmod \prod_i b_i$, from which we derive exact round-tripping of
numbers below the capacity $\prod_i b_i$, validity of extracted digits, the value bound for valid
digit lists, and the uniqueness theorem $\mdigits(bs, \mval(bs, ds)) = ds$. Together these assemble
into an explicit bijection $\{0, \dots, \prod_i b_i - 1\} \cong \{\text{valid digit lists}\}$. The
construction is a conservative extension of the classical theory: on a uniform base list it restricts
exactly to standard base-$b$ evaluation, recovering the classical positional-system theorem as a
corollary. Two specializations are highlighted: the uniform base-$b$ system and the factorial number
system $[2, 3, \dots, k+1]$ of capacity $(k+1)!$. Every result has been formally verified.
\end{abstract}

\maketitle

\section{Introduction}
A positional numeral system makes two promises about every number $n$ in its range: that $n$ can be
written as a string of digits (\emph{existence}), and that it can be so written in exactly one way
using legal digits (\emph{uniqueness}). The base-$b$ system fulfils both, and its ubiquity has made
the uniformity of its base feel essential. It is not. What makes a positional system work is not that
the bases are equal but that each digit is bounded by its own position's base. Once stated this way,
existence and uniqueness extend verbatim to systems in which every position carries a different base.
We call these \emph{mixed-radix} or \emph{alien} systems; they include ordinary base-$b$ arithmetic,
the factorial number system, the primorial system, and the mixed bases of clocks and calendars.

We give a complete, self-contained development built on a single identity --- the master
reconstruction law --- with a formal verification of every statement. The argument avoids well-founded
recursion in favour of structural recursion on the list of bases.

\section{Definitions}
Numbers are nonnegative integers ($\NN$) and lists are written least significant first. We write
$\prod bs$ for the product of the entries of $bs$ (empty product $=1$) and $|ds|$ for length.

\begin{definition}[Value / Horner evaluation \texttt{mval}]
$\mval(bs, [\,]) = 0$, $\ \mval([\,], d :: ds') = d$, and
$\mval(b :: bs',\, d :: ds') = d + b \cdot \mval(bs', ds')$. On equal-length lists,
$\mval(bs, ds) = d_0 + b_0(d_1 + b_1(d_2 + \cdots + b_{k-2} d_{k-1}))$.
\end{definition}

\begin{definition}[Digit extraction \texttt{mdigits}]
$\mdigits([\,], n) = [\,]$ and $\mdigits(b :: bs',\, n) = (n \bmod b) :: \mdigits(bs',\, \lfloor n/b\rfloor)$.
\end{definition}

\begin{definition}[Capacity]
The capacity of $bs$ is $\prod bs = \prod_i b_i$ (with $\prod [\,] = 1$).
\end{definition}

\begin{definition}[Valid digit list]
$ds$ is valid for $bs$ when $\Forall(<)\,ds\,bs$, i.e. $|ds| = |bs|$ and $d_i < b_i$ for all $i$.
\end{definition}

\section{Elementary structural facts}
\begin{lemma}[\texttt{mval\_nil\_right}]
$\mval(bs, [\,]) = 0$ for every $bs$.
\end{lemma}
\begin{proof} Case split on $bs$; both cases reduce to a defining equation. \end{proof}

\begin{lemma}[\texttt{mdigits\_length}]
$|\mdigits(bs, n)| = |bs|$ for all $n$.
\end{lemma}
\begin{proof} Induction on $bs$, generalizing $n$. \end{proof}

\section{The master reconstruction law and existence}
\begin{theorem}[Master reconstruction law, \texttt{mval\_mdigits}]
\label{thm:master}
For every base list $bs$ and every $n \in \NN$,
\[ \mval\big(bs,\ \mdigits(bs, n)\big) = n \bmod \textstyle\prod bs. \]
\end{theorem}
\begin{proof}
Induction on $bs$, generalizing $n$. For $bs = [\,]$ both sides are $0$ (since $n \bmod 1 = 0$). For
$bs = b :: bs'$, the definitions give
$\mval(b :: bs', \mdigits(b::bs', n)) = (n \bmod b) + b \cdot \mval(bs', \mdigits(bs', \lfloor n/b\rfloor))$,
and the induction hypothesis turns the second factor into $\lfloor n/b\rfloor \bmod \prod bs'$. The goal
reduces to $n \bmod (b \cdot m) = (n \bmod b) + b(\lfloor n/b\rfloor \bmod m)$ with $m = \prod bs'$,
which is the decomposition of a remainder modulo a product (\texttt{Nat.mod\_mul}).
\end{proof}

\begin{corollary}[Exact round trip below capacity, \texttt{mval\_mdigits\_of\_lt}]
\label{cor:exist}
If $n < \prod bs$ then $\mval(bs, \mdigits(bs, n)) = n$.
\end{corollary}
\begin{proof} Theorem~\ref{thm:master} and $n \bmod \prod bs = n$ when $n < \prod bs$. \end{proof}

\begin{lemma}[Extracted digits are valid, \texttt{mdigits\_forall2\_lt}]
\label{lem:valid}
If every base is positive, then $\Forall(<)\,(\mdigits(bs, n))\,bs$.
\end{lemma}
\begin{proof}
Induction on $bs$. The head digit $n \bmod b < b$ by $\texttt{Nat.mod\_lt}$ (using $b > 0$); the tail
is valid by the induction hypothesis on $\lfloor n/b\rfloor$.
\end{proof}

\section{The bound and uniqueness}
\begin{lemma}[Value bound, \texttt{mval\_lt\_prod}]
\label{lem:bound}
If $\Forall(<)\,ds\,bs$ then $\mval(bs, ds) < \prod bs$.
\end{lemma}
\begin{proof}
Induction on the $\Forall_2$ witness. Empty: $0 < 1$. Cons with $d < b$ and $v := \mval(bs', ds') < \prod bs'$:
$d + b v \le (b-1) + b(\prod bs' - 1) = b \prod bs' - 1 < \prod(b :: bs')$.
\end{proof}
The maximal valid list $d_i = b_i - 1$ attains $\prod bs - 1$, one below capacity.

\begin{theorem}[Uniqueness, \texttt{mdigits\_mval}]
\label{thm:unique}
If $\Forall(<)\,ds\,bs$ then $\mdigits(bs, \mval(bs, ds)) = ds$.
\end{theorem}
\begin{proof}
Induction on $ds$, generalizing $bs$. For $ds = d :: ds'$, $bs = b :: bs'$, set $v = \mval(bs', ds')$ so
$\mval(bs, ds) = d + b v$ with $d < b$. Then $(d + b v) \bmod b = d$ and $\lfloor (d + b v)/b\rfloor = v$
(since $\lfloor d/b\rfloor = 0$). The induction hypothesis gives $\mdigits(bs', v) = ds'$, so
$\mdigits(b :: bs', d + b v) = d :: ds' = ds$.
\end{proof}

\section{The crowning bijection}
\begin{theorem}[Mixed-radix bijection, \texttt{mixedRadixEquiv}]
For $bs$ with all bases positive, $\Phi(n) = \mdigits(bs, n)$ is a bijection
$\{0, \dots, \prod bs - 1\} \to \{ds : \Forall(<)\,ds\,bs\}$ with inverse $\Psi(ds) = \mval(bs, ds)$.
\end{theorem}
\begin{proof}
Well-definedness of $\Phi$ is Lemma~\ref{lem:valid}; of $\Psi$, Lemma~\ref{lem:bound}.
$\Psi \circ \Phi = \mathrm{id}$ is Corollary~\ref{cor:exist}; $\Phi \circ \Psi = \mathrm{id}$ is
Theorem~\ref{thm:unique}. The source is realized as $\mathrm{Fin}(\prod bs)$.
\end{proof}

\section{Conservative extension: recovering classical base-$N$}
Let $\mathrm{replicate}(k, b)$ be the list of $k$ copies of $b$.
\begin{lemma}[\texttt{prod\_replicate}] $\prod \mathrm{replicate}(k, b) = b^k$. \end{lemma}
\begin{theorem}[Restriction to classical evaluation, \texttt{mval\_replicate\_eq\_ofDigits}]
For all $b$, all $ds$, and all $k \ge |ds|$, $\mval(\mathrm{replicate}(k, b), ds) = \ofDigits(b, ds)$,
where $\ofDigits(b, ds) = d_0 + b\,d_1 + b^2 d_2 + \cdots$.
\end{theorem}
\begin{proof}
Induction on $ds$; the side-condition $k \ge |ds|$ keeps a base available per digit, and the cons step
matches the recurrence $\ofDigits(b, d :: ds') = d + b \cdot \ofDigits(b, ds')$.
\end{proof}
\begin{corollary}[Classical positional theorem, \texttt{uniform\_roundtrip}]
If $n < b^k$ then $\mval(\mathrm{replicate}(k, b), \mdigits(\mathrm{replicate}(k, b), n)) = n$.
\end{corollary}
\begin{proof} Corollary~\ref{cor:exist} with capacity $b^k$. \end{proof}

\section{The factorial number system}
\begin{definition}[Factorial bases]
$bs = [2, 3, 4, \dots, k+1]$, i.e. $b_i = i + 2$.
\end{definition}
\begin{proposition} $\prod [2, 3, \dots, k+1] = (k+1)!$. \end{proposition}
Specializing the bijection gives $\{0, \dots, (k+1)! - 1\} \cong \{\text{valid factoradic lists}\}$ with
$d_i \le i + 1$. The factoradic digit strings are the Lehmer codes of permutations, so counting
$0, \dots, (k+1)! - 1$ enumerates $\Perm(\{0, \dots, k\})$ lexicographically.

\section{Worked examples}
We work three examples by hand, exhibiting both round trips.

\emph{Base ten.} With $bs = [10,10,10]$ ($\prod bs = 1000$), encoding $723$ gives successive
remainders/quotients $(3,72), (2,7), (7,0)$, so $\mdigits(bs,723) = [3,2,7]$ and
$\mval(bs,[3,2,7]) = 3 + 10(2 + 10\cdot 7) = 723$.

\emph{Factorial base.} With $bs = [2,3,4,5]$ ($\prod bs = 5! = 120$), encoding $100$ gives
$(0,50),(2,16),(0,4),(4,0)$, so $\mdigits(bs,100) = [0,2,0,4]$; with place values $1!,2!,3!,4! = 1,2,6,24$,
$\mval = 0\cdot 1 + 2\cdot 2 + 0\cdot 6 + 4\cdot 24 = 100$. The maximal numeral $[1,2,3,4]$ encodes
$119 = 120 - 1$, the extremal case of Lemma~\ref{lem:bound}.

\emph{Primorial base.} With $bs = [2,3,5,7]$ ($\prod bs = 210$), encoding $209$ gives
$(1,104),(2,34),(4,6),(6,0)$, so $\mdigits(bs,209) = [1,2,4,6]$ with $\mval = 209 = 210 - 1$.
The successive-division digits differ in general from the bare residues $(n \bmod p_i)$; their precise
relationship is Conjecture~5 below.

\section{Algorithms and complexity}
Encoding $\mdigits$ uses one Euclidean division per base, $O(k)$; decoding $\mval$ uses one multiply-add
per base via Horner's rule, $O(k)$; validity is an $O(k)$ scan. Both round trips are linear in the number
of positions.

\section{Applications}
Combinatorial ranking/unranking via the factorial system; time/calendar arithmetic with base
$[60, 60, 24, \dots]$; primorial/residue systems linked to the Chinese Remainder Theorem; mixed-radix
counters in hardware and combinatorial generation.

\section{Discussion}
The entire theory reduces to Theorem~\ref{thm:master}, whose only non-formal ingredient is
\texttt{Nat.mod\_mul}. Indexing validity by the pairwise relation $\Forall(<)$ rather than position-indexed
inequalities lets both round trips, the bound, and the bijection fall out of plain list induction; recursing
on the base list rather than on $n$ avoids well-founded recursion. The conservative-extension theorems confirm
this is a true generalization rather than a parallel reimplementation.

Uniform base-$b$ representation, the factorial number system, and residue number systems are usually presented
as separate constructions, each with its own existence/uniqueness proof; the mixed-radix viewpoint unifies the
non-redundant, positive-base members of this family, each being the instance of a particular base list whose
representation theorem is a single corollary of Theorem~\ref{thm:master}. The choice of capacity as the product
$\prod_i b_i$ rather than a power is the structural invariant that makes the unification possible. Redundant
systems (signed-digit, non-adjacent forms) and greedy-but-non-positional systems (Zeckendorf) fall outside the
strict $d_i < b_i$ condition and require the weaker super-increasing place-value hypothesis of Conjecture~4.
Because every statement is machine-checked, the framework can serve as a verified foundation for those
extensions and the applications above.

\section{Future directions}
\begin{conjecture}[Order isomorphism]
The bijection is an order isomorphism from $\mathrm{Fin}(\prod bs)$ to valid digit lists under
reverse-lexicographic comparison: $m < n \iff \mathrm{reverse}(\mdigits(bs, m)) <_{\mathrm{lex}} \mathrm{reverse}(\mdigits(bs, n))$.
\end{conjecture}
\begin{conjecture}[Factoradic $\leftrightarrow$ permutations]
There is an explicit bijection $\mathrm{Fin}((k+1)!) \cong \Perm(\mathrm{Fin}(k+1))$ through the factoradic
digits (the Lehmer code), monotone for the lexicographic order on permutations.
\end{conjecture}
\begin{conjecture}[Carry-free addition]
$a + b$ has no carries in base $bs$ iff $d_i(a) + d_i(b) < b_i$ for all $i$; the digit-sum subadditivity
$s(a+b) \le s(a) + s(b)$ holds for any base list with equality exactly in the carry-free case, where
$s_{bs}(n) = \sum \mdigits(bs, n)$.
\end{conjecture}
\begin{conjecture}[Greedy $=$ canonical for super-increasing bases]
For place values $P_i = \prod_{j<i} b_j$ super-increasing, the greedy $\mdigits$ gives the unique
representation; a common generalization \texttt{GreedyRepresentation} of \texttt{MixedRadix.mdigits} and
\texttt{Nat.zeckendorf} should subsume both uniqueness theorems.
\end{conjecture}
\begin{conjecture}[Primorial / mixed analytic bases]
For the primorial base $[p_0, \dots, p_{k-1}]$ of capacity $p_k\#$, the digit map is compatible with the CRT
isomorphism $\mathbb{Z}/p_k\# \cong \prod \mathbb{Z}/p_i$ up to the triangular Horner change of basis, giving a
positional/residue duality.
\end{conjecture}

\section{Conclusion}
Stripping uniformity from positional notation costs nothing: existence, uniqueness, and an explicit bijection
between numbers and valid numerals all survive when each position carries its own base. The master law
$\mval(bs, \mdigits(bs, n)) = n \bmod \prod bs$ is the engine; the bijection
$\mathrm{Fin}(\prod bs) \cong \{\text{valid digit lists}\}$ is what it builds; base ten is one point in a
continent.

